class T(unittest.TestCase):
 def test_all(self):
  r=FakeRepository();a=handler({'httpMethod':'GET','path':'/health'},repo=r);self.assertEqual(a['statusCode'],200);a=handler(e(),repo=r);self.assertEqual(a['statusCode'],201);self.assertEqual(r.by_key['k1']['form']['phone'],'+79990000001');self.assertNotIn('raw_payload',r.by_key['k1']);b=handler(e(),repo=r);self.assertEqual(b['statusCode'],200);self.assertEqual(handler(e({**P,'full_name':'changed'},'k1'),repo=r)['statusCode'],409);self.assertEqual(handler(e({**P,'personal_data_consent':False},'k2'),repo=r)['statusCode'],422);self.assertEqual(handler(e({**P,'age':20},'k3'),repo=r)['statusCode'],422);self.assertEqual(handler(e({**P,'email':'bad'},'k4'),repo=r)['statusCode'],422);self.assertEqual(handler(e({**P,'public_profile_url':'ftp://x'},'k5'),repo=r)['statusCode'],422);self.assertEqual(handler(e({**P,'city':'Сочи'},'k6'),repo=r)['statusCode'],422);self.assertEqual(handler(e({**P,'consent_version':'bad'},'k7'),repo=r)['statusCode'],422)
